INSERT INTO `lessons` VALUES (1,NULL,NULL,'حرف الراء هو أول حرف نتعلمه. شكله مثل الذيل المنحني. كلمات: رمان، رسم، ريشة، رجل، رامي.',1,'[\"/uploads/images/ar1-p1/page006_img01.png\",\"/uploads/images/ar1-p1/page006_img02.jpeg\",\"/uploads/images/ar1-p1/page007_img01.png\",\"/uploads/images/ar1-p1/page007_img02.png\",\"/uploads/images/ar1-p1/page008_img01.png\",\"/uploads/images/ar1-p1/page008_img02.png\"]','التعرف إلى حرف الراء اسماً وشكلاً وصوتاً، قراءة وكتابة حرف الراء',1,NULL,1,NULL,'حرف الراء',1),(2,NULL,NULL,'حرف الدال شكله مثل الظهر المنحني. كلمات: دجاجة، دب، دار، ديك، دانا.',1,'[\"/uploads/images/ar1-p1/page009_img01.png\",\"/uploads/images/ar1-p1/page009_img02.png\",\"/uploads/images/ar1-p1/page010_img01.png\",\"/uploads/images/ar1-p1/page010_img02.png\",\"/uploads/images/ar1-p1/page011_img01.png\",\"/uploads/images/ar1-p1/page011_img02.png\",\"/uploads/images/ar1-p1/page011_img03.jpeg\",\"/uploads/images/ar1-p1/page012_img01.png\",\"/uploads/images/ar1-p1/page012_img02.png\",\"/uploads/images/ar1-p1/page012_img03.png\"]','التعرف إلى حرف الدال اسماً وشكلاً وصوتاً، قراءة وكتابة حرف الدال',2,NULL,1,NULL,'حرف الدال',1),(3,NULL,NULL,'حرف الباء شكله مثل الصحن وتحته نقطة واحدة. كلمات: بيت، بطة، باب، بقرة.',1,'[\"/uploads/images/ar1-p1/page013_img01.jpeg\",\"/uploads/images/ar1-p1/page014_img01.jpeg\",\"/uploads/images/ar1-p1/page015_img01.jpeg\",\"/uploads/images/ar1-p1/page016_img01.jpeg\"]','التعرف إلى حرف الباء اسماً وشكلاً وصوتاً، قراءة وكتابة حرف الباء',3,NULL,1,NULL,'حرف الباء',1),(4,NULL,NULL,'مراجعة حروف الراء والدال والباء. نتدرب على قراءتها وكتابتها.',1,'[\"/uploads/images/ar1-p1/page017_img01.png\",\"/uploads/images/ar1-p1/page018_img01.png\",\"/uploads/images/ar1-p1/page018_img02.png\",\"/uploads/images/ar1-p1/page018_img03.png\",\"/uploads/images/ar1-p1/page018_img04.png\",\"/uploads/images/ar1-p1/page018_img05.jpeg\",\"/uploads/images/ar1-p1/page018_img06.png\",\"/uploads/images/ar1-p1/page018_img07.jpeg\",\"/uploads/images/ar1-p1/page019_img01.png\"]