غر إلى الأكبر ومن الأكبر إلى الأصغر: ٠ ١ ٢ ٣ ٤ ٥ ٦ ٧ ٨ ٩',1,'[\"/uploads/images/ma1-p1/page020_img02.png\",\"/uploads/images/ma1-p1/page026_img01.png\"]','ترتيب الأعداد تصاعدياً وتنازلياً',5,NULL,1,NULL,'ترتيب الأعداد',5),(115,NULL,NULL,'كل عدد يتكون من أعداد أصغر. مثلاً: ٥ = ٢ + ٣ أو ٥ = ١ + ٤',1,'[\"/uploads/images/ma1-p1/page035_img04.png\",\"/uploads/images/ma1-p1/page035_img06.png\"]','تحليل الأعداد إلى مكوناتها',6,NULL,1,NULL,'مكونات الأعداد',5),(116,NULL,NULL,'نتعلم عملية الجمع. الجمع يعني نضيف: ٢ + ١ = ٣. نجمع أعداداً نتيجتها ٥ أو أقل.',1,'[\"/uploads/images/ma1-p1/page037_img09.png\",\"/uploads/images/ma1-p1/page037_img10.png\",\"/uploads/images/ma1-p1/page037_img11.png\"]','إجراء عمليات جمع بسيطة ضمن العدد 5',7,NULL,1,NULL,'الجمع ضمن ٥',5),(117,NULL,NULL,'نجمع أعداداً أكبر نتيجتها ٩ أو أقل: ٤ + ٣ = ٧، ٥ + ٤ = ٩',1,'[\"/uploads/images/ma1-p1/page049_img1047.png\",\"/uploads/images/ma1-p1/page049_img1151.png\",\"/uploads/images/ma1-p1/page049_img1317.png\",\"/uploads/images/ma1-p1/page049_img1353.png\",\"/uploads/images/ma1-p1/page049_img462.png\",\"/uploads/images/ma1-p1/page049_img851.png\",\"/uploads/images/ma1-p1/page049_img961.png\"]','إجراء عمليات جمع ضمن العدد 9',8,NULL,1,NULL,'الجمع ضمن ٩',5),(118,NULL,NULL,'نتعلم عملية الطرح. الطرح يعني نأخذ: ٥ - ٢ = ٣. نطرح أعداداً من ٥ أو أقل.',1,'[\"/uploads/images/ma1-p1/page050_img11.png\",\"/uploads/images/ma1-p1/page050_img12.png\"]','إجراء عمليات طرح بسيطة ضمن العدد 5',9,NULL,1,NULL,'الطرح ضمن ٥',5),(119,NULL,NULL,'نطرح أعداداً أكبر: ٩ - ٣ = ٦، ٨ - ٥ = ٣',1,'[\"/uploads/images/ma1-p1/page060_img01.png\",\"/uploads/images/ma1-p1/page060_img04.png\",\"/uploads/images/ma1-p1/page064_img02.png\",\"/uploads/images/ma1-p1/page064_img03.png\",\"/uploads/images/ma1-p1/page064_img04.png\",\"/uploads/images/ma1-p1/page064_img05.png\",\"/uploads/images/ma1-p1/page064_img06.png\",\"/uploads/images/ma1-p1/page064_img07.png\",\"/uploads/images/ma1-p1/page064_img09.png\",\"/uploads/images/ma1-p1/page064_img10.png\",\"/uplo