ages/ma1-p2/page101_img12.jpeg\",\"/uploads/images/ma1-p2/page101_img14.jpeg\",\"/uploads/images/ma1-p2/page103_img12.jpeg\",\"/uploads/images/ma1-p2/page103_img14.jpeg\",\"/uploads/images/ma1-p2/page104_img10.jpeg\",\"/uploads/images/ma1-p2/page104_img11.jpeg\",\"/uploads/images/ma1-p2/page105_img14.jpeg\",\"/uploads/images/ma1-p2/page105_img15.jpeg\",\"/uploads/images/ma1-p2/page105_img16.jpeg\",\"/uploads/images/ma1-p2/page106_img08.jpeg\",\"/uploads/images/ma1-p2/page107_img19.png\",\"/uploads/images/ma1-p2/page108_img11.jpeg\",\"/uploads/images/ma1-p2/page109_img01.jpeg\",\"/uploads/images/ma1-p2/page109_img02.jpeg\",\"/uploads/images/ma1-p2/page109_img13.jpeg\",\"/uploads/images/ma1-p2/page109_img24.jpeg\",\"/uploads/images/ma1-p2/page109_img26.jpeg\",\"/uploads/images/ma1-p2/page109_img30.jpeg\",\"/uploads/images/ma1-p2/page109_img33.png\",\"/uploads/images/ma1-p2/page111_img23.jpeg\"]','مراجعة نهائية شاملة',11,NULL,2,NULL,'مراجعة نهائية',5),(136,NULL,NULL,'نقارن العددين بكتابة < أو > أو =. مثلاً: ٤٧ > ٢٩ لأن ٤٧ أكبر من ٢٩.',2,NULL,'إجراء المقارنة بين عددين ضمن ٩٩ باستخدام الإشارات الثلاث.',1,NULL,1,NULL,'المقارنة بين عددين ضمن ٩٩',6),(137,NULL,NULL,'نرتّب الأعداد تصاعدياً (من الأصغر إلى الأكبر) أو تنازلياً (من الأكبر إلى الأصغر).',2,NULL,'ترتيب أعداد ضمن ٩٩ تصاعدياً وتنازلياً.',2,NULL,1,NULL,'ترتيب الأعداد ضمن ٩٩',6),(138,NULL,NULL,'كل عدد من رقمين له خانة آحاد وخانة عشرات. مثال: ٧٤ = ٧ عشرات + ٤ آحاد.',2,NULL,'تحليل العدد إلى آحاد وعشرات، معرفة القيمة المنزلية.',3,NULL,1,NULL,'القيمة المنزلية ضمن ٩٩',6),(139,NULL,NULL,'العدد الزوجي ينتهي بـ ٠ أو ٢ أو ٤ أو ٦ أو ٨. العدد الفردي ينتهي بـ ١ أو ٣ أو ٥ أو ٧ أو ٩.',2,NULL,'التمييز بين العدد الزوجي والعدد الفردي.',4,NULL,1,NULL,'العدد الزوجي والعدد الفردي',6),(140,NULL,NULL,'مراجعة شاملة على وحدة الأعداد ضمن ٩٩: المقارنة، الترتيب، القيمة المنزلية، الزوجي والفردي.',2,NULL,'مراجعة جميع المفاهيم في الوحدة الأولى.',5,NULL,1,NULL,'مراجعة الوحدة الأولى (الأعداد ضمن ٩٩)',6),(141,NULL,NULL,'نجمع عددين ضمن ٩٩ بدون حمل: نجمع الآحاد مع الآحاد، والعشرات مع العشرات. مثال: ٢٣ + ٤٥ = ٦٨.',2,NULL,'إجراء عمليات جمع ضمن ٩٩ بدون حمل.',6,NULL,1,NULL,'الجمع ضمن ٩٩ دون حمل',6),(142,NULL,NULL,'نطرح عددين ضمن ٩٩ بدون استلاف: نطرح الآحاد من الآحاد، والعشرات من العشرات. مثال: ٤٧ − ٢٣ = ٢٤.',2,NULL,'إجراء عمليات طرح ضمن ٩٩ بدون استلاف.',7,NULL,1,NULL,'طرح عددين ضمن ٩٩ دون استلاف',6),(143,NULL,NULL,'مراجعة شاملة على عمليتي الجمع والطرح ضمن ٩٩.',2,NULL,'مراجعة مهارات الجمع والطرح ضمن ٩٩.',8,NULL,1,NULL,'مراجعة الوحدة الثانية (الجمع والطرح ضمن ٩٩)',6),(144,NULL,NULL,'نتعلم الأعداد من ١٠٠ إلى ١٩٩. كل عدد من ثلاثة أرقام: مئات وعشرات وآحاد.',2,NULL,'قراءة وكتابة الأعداد ضمن ١٩٩.',9,NULL,1,NULL,'الأعداد ضمن ١٩٩',6),(145,NULL,NULL,'نتعلم الأعداد حتى ٩٩٩. كل عدد فيه مئات وعشرات وآحاد. مثال: ٤٢٧ = ٤ مئات + ٢ عشرات + ٧ آحاد.',2,NULL,'قراءة وكتابة الأعداد ضمن ٩٩٩.',10,NULL,1,NULL,'الأعداد ضمن ٩٩٩',6),(146,NULL,NULL,'كل عدد من ثلاثة أرقام له ثلاث منازل: المئات والعشرات والآحاد. مثال: في العدد ٢٥٧، الرقم ٢ في خانة المئات.',2,NULL,'تحديد منزلة الرقم في العدد ضمن ٩٩٩.',11,NULL,1,NULL,'القيمة المنزلية للأعداد ضمن ٩٩٩',6),(147,NULL,NULL,'نقارن الأعداد ضمن ٩٩٩ بالنظر إلى المئات أولاً، ثم العشرات، ثم الآحاد.',2,NULL,'مقارنة عددين ضمن ٩٩٩.',12,NULL,1,NULL,'مقارنة الأعداد ضمن ٩٩٩',6),(148,NULL,NULL,'نرتّب أعداداً ضمن ٩٩٩ تصاعدياً أو تنازلياً بناءً على المئات والعشرات والآحاد.',2,NULL,'ترتيب أعداد ضمن ٩٩٩.',13,NULL,1,NULL,'ترتيب الأعداد ضمن ٩٩٩',6),(149,NULL,NULL,'حكم الأعداد الزوجية والفردية في الأعداد المكوّنة من ثلاثة أرقام يعتمد على آحادها: إذا كانت ٠ أو ٢ أو ٤ أو ٦ أو ٨ فهي زوجية.',2,NULL,'تمييز الأعداد الزوجية والفردية في نطاق ٩٩٩.',14,NULL,1,NULL,'الأعداد الزوجية والفردية ضمن ٩٩٩',6),(150,NULL,NULL,'مراجعة شاملة على الأعداد ضمن ٩٩٩.',2,NULL,'مراجعة جميع مفاهيم الوحدة الثالثة.',15,NULL,1,NULL,'مراجعة الوحدة الثالثة (الأعداد ضمن ٩٩٩)',6),(151,NULL,NULL,'القطعة المستقيمة لها طرفان وتمتد بخط مستقيم. الخط المنحني يلتوي ولا يستقيم.',2,NULL,'التمييز بين القطعة المستقيمة والخط المنحني.',16,NULL,1,NULL,'القطعة المستقيمة والخط المنحني',6),(152,NULL,NULL,'المربع شكل هندسي له أربعة أضلاع متساوية وأربع زوايا قائمة. مثل وجه المكعب وشاشة بعض الصور.',2,NULL,'التعرف على المربع وخصائصه.',17,NULL,1,NULL,'المربع',6),(153,NULL,NULL,'المستطيل شكل هندسي له أربعة أضلاع: كل ضلعين متقابلين متساويان، وله أربع زوايا قائمة.',2,NULL,'التعرف على المستطيل وخصائصه والفرق بينه وبين المربع.',18,NULL,1,NULL,'المستطيل',6),(154,NULL,NULL,'المثلث شكل هندسي له ثلاثة أضلاع وثلاث زوايا وثلاثة رؤوس. مثل سقف بعض البيوت.',2,NULL,'التعرف على المثلث وخصائصه.',19,NULL,1,NULL,'المثلث',6),(155,NULL,NULL,'الدائرة شكل هندسي بلا أضلاع ولا زوايا. مركزها نقطة، وكل النقاط على الحدود تبعد عن المركز بالمسافة نفسها.',2,NULL,'التعرف على الدائرة وخصائصها.',20,NULL,1,NULL,'الدائرة',6),(156,NULL,NULL,'مراجعة شاملة على القطعة المستقيمة، المربع، المستطيل، المثلث، الدائرة.',2,NULL,'مراجعة الأشكال الهندسية الأساسية.',21,NULL,1,NULL,'مراجعة الوحدة الرابعة (الهندسة والقياس ١)',6),(157,NULL,NULL,'البيانات معلومات نجمعها لنفهم الواقع. مثلاً عدد الطلاب في كل صف، أو عدد كل لون من الأقلام.',2,NULL,'تعريف البيانات وجمعها.',22,NULL,1,NULL,'البيانات',6),(158,NULL,NULL,'نمثّل البيانات بالصور: كل صورة تدلّ على شيء. مثلاً لكل صورة تفاحة، رمز لشخص أكل تفاحة. التمثيل بالصور يجعل البيانات سهلة الفهم.',2,NULL,'تعلّم تمثيل البيانات بالصور.',23,NULL,1,NULL,'تمثيل البيانات بالصور',6),(159,NULL,NULL,'مراجعة شاملة على جمع البيانات وتمثيلها بالصور.',2,NULL,'مراجعة مفاهيم الوحدة الخامسة.',24,NULL,1,NULL,'مراجعة الوحدة الخامسة (البيانات)',6),(160,NULL,NULL,'نجمع عددين ضمن ٩٩٩ بدون حمل: نجمع الآحاد مع الآحاد، والعشرات مع العشرات، والمئات مع المئات.',2,NULL,'إجراء جمع ضمن ٩٩٩ دون حمل.',1,NULL,2,NULL,'جمع عددين دون حمل ضمن ٩٩٩',6),(161,NULL,NULL,'إذا كان مجموع الآحاد ≥ ١٠ نحمل ١ إلى خانة العشرات. مثال: ٢٧ + ١٥ = ٤٢ (نحمل من الآحاد).',2,NULL,'إجراء عمليات جمع مع الحمل.',2,NULL,2,NULL,'جمع عددين مع الحمل',6),(162,NULL,NULL,'نطرح عددين ضمن ٩٩٩ بدون استلاف: نطرح الآحاد من الآحاد، والعشرات من العشرات، والمئات من المئات.',2,NULL,'إجراء طرح ضمن ٩٩٩ دون استلاف.',3,NULL,2,NULL,'طرح عددين دون استلاف ضمن ٩٩٩',6),(163,NULL,NULL,'إذا كانت آحاد المطروح منه أصغر من آحاد المطروح، نستلف عشرة من خانة العشرات. مثال: ٥٢ − ٢٧ = ٢٥.',2,NULL,'إجراء عمليات طرح مع الاستلاف.',4,NULL,2,NULL,'طرح عددين مع الاستلاف',6),(164,NULL,NULL,'للجمع خاصيتان: التبديل (يجوز تبديل ترتيب العددين فيُعطى الناتج نفسه)، والتجميع (يجوز تجميع الأعداد المتتالية بأي ترتيب).',2,NULL,'فهم خاصيتي التبديل والتجميع في الجمع.',5,NULL,2,NULL,'خواص عملية الجمع',6),(165,NULL,NULL,'مراجعة شاملة على الجمع والطرح ضمن ٩٩٩ مع/بدون حمل واستلاف، وخواص الجمع.',2,NULL,'مراجعة الوحدة السادسة.',6,NULL,2,NULL,'مراجعة الوحدة السادسة (جمع وطرح ضمن ٩٩٩)',6),(166,NULL,NULL,'العدد القفزي يعني العدّ بقفزات متساوية. مثال: عدّ بـ ٢: ٢، ٤، ٦، ٨، ١٠.',2,NULL,'تعلّم العدّ القفزي تمهيداً للضرب.',7,NULL,2,NULL,'العدد القفزي',6),(167,NULL,NULL,'الضرب هو جمع متكرّر لنفس العدد. مثال: ٣ × ٤ = ٤ + ٤ + ٤ = ١٢ (٣ مرّات ٤).',2,NULL,'فهم الضرب كجمع متكرّر.',8,NULL,2,NULL,'مفهوم الضرب',6),(168,NULL,NULL,'حقائق ضرب العدد ٢: ٢×١=٢، ٢×٢=٤، ٢×٣=٦، ٢×٤=٨، ٢×٥=١٠، ٢×٦=١٢، ٢×٧=١٤، ٢×٨=١٦، ٢×٩=١٨، ٢×١٠=٢٠.',2,NULL,'حفظ جدول ضرب ٢.',9,NULL,2,NULL,'حقائق الضرب للعدد ٢',6),(169,NULL,NULL,'حقائق ضرب العدد ٣: ٣×١=٣، ٣×٢=٦، ٣×٣=٩، ٣×٤=١٢، ٣×٥=١٥، ٣×٦=١٨، ٣×٧=٢١، ٣×٨=٢٤، ٣×٩=٢٧، ٣×١٠=٣٠.',2,NULL,'حفظ جدول ضرب ٣.',10,NULL,2,NULL,'حقائق الضرب للعدد ٣',6),(170,NULL,NULL,'حقائق ضرب العدد ٤: ٤×١=٤، ٤×٢=٨، ٤×٣=١٢، ٤×٤=١٦، ٤×٥=٢٠، ٤×٦=٢٤، ٤×٧=٢٨، ٤×٨=٣٢، ٤×٩=٣٦، ٤×١٠=٤٠.',2,NULL,'حفظ جدول ضرب ٤.',11,NULL,2,NULL,'حقائق الضرب للعدد ٤',6),(171,NULL,NULL,'حقائق ضرب العدد ٥: ٥×١=٥، ٥×٢=١٠، ٥×٣=١٥، ٥×٤=٢٠، ٥×٥=٢٥، ٥×٦=٣٠، ٥×٧=٣٥، ٥×٨=٤٠، ٥×٩=٤٥، ٥×١٠=٥٠.',2,NULL,'حفظ جدول ضرب ٥.',12,NULL,2,NULL,'حقائق الضرب للعدد ٥',6),(172,NULL,NULL,'حقائق ضرب العدد ١٠: ١٠×١=١٠، ١٠×٢=٢٠، ١٠×٣=٣٠، ... ١٠×٩=٩٠، ١٠×١٠=١٠٠. ضرب أيّ عدد في ١٠ يعني إضافة صفر إلى يمينه.',2,NULL,'حفظ جدول ضرب ١٠ وفهم قاعدة \'إضافة الصفر\'.',13,NULL,2,NULL,'حقائق الضرب للعدد ١٠',6),(173,NULL,NULL,'مراجعة شاملة على جداول الضرب ٢، ٣، ٤، ٥، ١٠.',2,NULL,'مراجعة جداول الضرب.',14,NULL,2,NULL,'مراجعة الوحدة السابعة (الضرب)',6),(174,NULL,NULL,'القسمة هي التوزيع بالتساوي. مثال: ١٢ ÷ ٣ = ٤، نوزع ١٢ على ٣ فيكون لكل واحد ٤. القسمة عكس الضرب.',2,NULL,'فهم القسمة كتوزيع متساوٍ وعكس للضرب.',15,NULL,2,NULL,'مفهوم القسمة',6),(175,NULL,NULL,'نتدرّب على قسمة الأعداد البسيطة: ٦ ÷ ٢، ٨ ÷ ٢، ٩ ÷ ٣، ١٠ ÷ ٥، ١٢ ÷ ٤، ١٥ ÷ ٣.',2,NULL,'إتقان القسمة لأعداد ضمن جدول الضرب.',16,NULL,2,NULL,'القسمة (١)',6),(176,NULL,NULL,'نتدرّب على قسمة أعداد أكبر باستخدام جدول الضرب: ٤٥ ÷ ٥، ٤٨ ÷ ٤، ٤٢ ÷ ٧.',2,NULL,'حلّ مسائل قسمة باستخدام جدول الضرب.',17,NULL,2,NULL,'القسمة (٢)',6),(177,NULL,NULL,'مراجعة شاملة على القسمة.',2,NULL,'مراجعة مهارات القسمة.',18,NULL,2,NULL,'مراجعة الوحدة الثامنة (القسمة)',6),(178,NULL,NULL,'الكسر يعني جزءاً من كلّ. ½ يعني نصف، ⅓ يعني ثلث، ¼ يعني ربع. مثلاً ½ تفاحة هو نصف تفاحة.',2,NULL,'فهم الكسور البسيطة: نصف، ثلث، ربع.',19,NULL,2,NULL,'الكسور (١، ½، ⅓، ¼)',6),(179,NULL,NULL,'نتعلم كسوراً جديدة: ⅕ (خُمس) و ⅛ (ثُمن). كلما زاد المقام (٥، ٨)، صار الجزء أصغر.',2,NULL,'فهم الكسور ⅕ و ⅛.',20,NULL,2,NULL,'الكسور (⅕، ⅛)',6),(180,NULL,NULL,'مراجعة شاملة على الكسور البسيطة.',2,NULL,'مراجعة المفاهيم الأساسية للكسور.',21,NULL,2,NULL,'مراجعة الوحدة التاسعة (الكسور)',6),(181,NULL,NULL,'نقيس الأطوال بوحدات: السنتيمتر للأشياء الصغيرة، المتر للأشياء الكبيرة، الكيلومتر للمسافات البعيدة. ١ متر = ١٠٠ سنتيمتر.',2,NULL,'التعرّف على وحدات قياس الطول.',22,NULL,2,NULL,'وحدات الطول',6),(182,NULL,NULL,'للساعة عقربان: العقرب القصير للساعات، الطويل للدقائق. عند ١٢ بالعقرب الطويل تكون الساعة تامّة. اليوم ٢٤ ساعة، الساعة ٦٠ دقيقة.',2,NULL,'قراءة الساعة في الساعات التامّة، معرفة عدد الساعات في اليوم.',23,NULL,2,NULL,'قراءة الساعة',6),(183,NULL,NULL,'المجسّمات هي الأشكال ثلاثية الأبعاد: المكعب (٦ وجوه مربعة)، الكرة (مدوّرة)، الأسطوانة (مثل العلبة).',2,NULL,'التعرّف على المجسّمات الأساسية.',24,NULL,2,NULL,'المجسّمات',6),(184,NULL,NULL,'مراجعة شاملة على وحدات الطول وقراءة الساعة والمجسّمات.',2,NULL,'مراجعة الوحدة العاشرة.',25,NULL,2,NULL,'مراجعة الوحدة العاشرة (الهندسة والقياس ٢)',6),(185,NULL,NULL,'نجمع البيانات بسؤال زملائنا ثم نسجّل الإجابات. مثلاً سؤال \'ما لونك المفضل؟\' فنحصل على أعداد الذين يحبّون كل لون.',2,NULL,'تعلّم خطوات جمع البيانات البسيطة.',26,NULL,2,NULL,'جمع البيانات البسيطة',6),(186,NULL,NULL,'نمثّل البيانات بصور أو أعمدة لقراءة سريعة وفهم أوضح. كل عمود ارتفاعه يدلّ على عدد ما يمثّله.',2,NULL,'التعرّف على التمثيلات البيانية البسيطة.',27,NULL,2,NULL,'التمثيلات البيانية',6),(187,NULL,NULL,'مراجعة شاملة على جمع البيانات وتمثيلها.',2,NULL,'مراجعة الوحدة الأخيرة.',28,NULL,2,NULL,'مراجعة الوحدة الحادية عشرة (البيانات ٢)',6),(188,NULL,NULL,'الله تعالى هو ربنا الذي خلقنا وخلق كل شيء. نحبه ونشكره على نعمه.',1,NULL,'التعرف على أن الله هو الخالق والرب',1,NULL,1,NULL,'الله ربي',7),(189,NULL,NULL,'أركان الإسلام خمسة: الشهادتان، الصلاة، الزكاة، صوم رمضان، حج البيت.',1,NULL,'حفظ أركان الإسلام الخمسة',2,NULL,1,NULL,'أركان الإسلام',7),(190,NULL,NULL,'سورة الفاتحة هي أول سورة في القرآن الكريم. نقرأها في كل صلاة. بسم الله الرحمن الرحيم.',1,NULL,'قراءة سورة الفاتحة وحفظها',3,NULL,1,NULL,'سورة الفاتحة',7),(191,NULL,NULL,'قل هو الله أحد، الله الصمد، لم يلد ولم يولد، ولم يكن له كفواً أحد.',1,NULL,'حفظ سورة الإخلاص وفهم معناها',4,NULL,1,NULL,'سورة الإخلاص',7),(192,NULL,NULL,'الله أنعم علينا بنعم كثيرة: السمع، البصر، الطعام، الماء، الأهل. نشكر الله على نعمه.',1,NULL,'التعرف على نعم الله وشكره عليها',5,NULL,1,NULL,'نعم الله تعالى',7),(193,NULL,NULL,'محمد ﷺ هو رسول الله وخاتم الأنبياء. ولد في مكة المكرمة. نحبه ونتبع سنته.',1,NULL,'التعرف على نبينا محمد ﷺ',6,NULL,1,NULL,'رسولنا محمد ﷺ',7),(194,NULL,NULL,'كان النبي ﷺ صادقاً أميناً رحيماً. كان يحب الأطفال ويعطف على الفقراء.',1,NULL,'التعرف على صفات الرسول ﷺ',7,NULL,1,NULL,'صفات الرسول ﷺ',7),(195,NULL,NULL,'نحب رسولنا محمد ﷺ ونتبع سنته. نصلي عليه ونقتدي بأخلاقه الحسنة.',1,NULL,'التعبير عن حب الرسول ﷺ',8,NULL,1,NULL,'أحب رسولي ﷺ',7),(196,NULL,NULL,'الصدق خلق جميل يحبه الله. الصادق يقول الحقيقة دائماً. رسولنا كان صادقاً.',1,NULL,'التعرف على أهمية الصدق',9,NULL,1,NULL,'الصدق',7),(197,NULL,NULL,'الأمانة أن نحفظ ما يعطينا الآخرون ونعيده لهم. الأمين محبوب عند الله والناس.',1,NULL,'التعرف على أهمية الأمانة',10,NULL,1,NULL,'الأمانة',7),(198,NULL,NULL,'نحترم الكبار ونساعدهم. نتكلم معهم بأدب ونستمع لنصائحهم.',1,NULL,'التعرف على أهمية احترام الكبار',11,NULL,1,NULL,'احترام الكبير',7),(199,NULL,NULL,'الوضوء طهارة للصلاة. خطواته: النية، غسل اليدين، المضمضة، الاستنشاق، غسل الوجه، غسل اليدين للمرفقين، مسح الرأس، غسل القدمين.',1,NULL,'التعرف على خطوات الوضوء',12,NULL,1,NULL,'الوضوء',7),(200,NULL,NULL,'الصلاة عبادة مهمة. نصلي ٥ مرات في اليوم: الفجر، الظهر، العصر، المغرب، العشاء.',1,NULL,'التعرف على أوقات الصلوات الخمس',13,NULL,1,NULL,'الصلاة',7),(201,NULL,NULL,'المسجد بيت الله. ندخله بالقدم اليمنى ونقول دعاء الدخول. نحافظ على نظافته وهدوئه.',1,NULL,'التعرف على آداب المسجد',14,NULL,1,NULL,'آداب المسجد',7),(202,NULL,NULL,'مراجعة شاملة: أركان الإسلام، سورة الفاتحة والإخلاص، صفات الرسول، الأخلاق، الوضوء والصلاة.',1,NULL,'مراجعة شاملة لمحتوى الفصل',15,NULL,1,NULL,'مراجعة عامة',7),(203,NULL,NULL,'قل أعوذ برب الناس، ملك الناس، إله الناس، من شر الوسواس الخناس.',1,NULL,'حفظ سورة الناس وفهم معناها',1,NULL,2,NULL,'سورة الناس',7),(204,NULL,NULL,'قل أعوذ برب الفلق، من شر ما خلق. الفلق هو الصبح.',1,NULL,'حفظ سورة الفلق وفهم معناها',2,NULL,2,NULL,'سورة الفلق',7),(205,NULL,NULL,'تبت يدا أبي لهب وتب. نتعلم تلاوة السورة.',1,NULL,'قراءة سورة المسد',3,NULL,2,NULL,'سورة المسد',7),(206,NULL,NULL,'الله خلق السماوات والأرض والجبال والبحار والحيوانات والنبات. كل شيء بديع وجميل.',1,NULL,'التأمل في خلق الله تعالى',4,NULL,2,NULL,'خلق الله تعالى',7),(207,NULL,NULL,'نسمّي الله قبل الأكل (بسم الله)، ونأكل باليد اليمنى، ونحمد الله بعد الأكل.',1,NULL,'التعرف على آداب الطعام في الإسلام',5,NULL,2,NULL,'آداب الطعام',7),(208,NULL,NULL,'النظافة من الإيمان. نغسل أيدينا، ننظف أسناننا، نحافظ على نظافة ملابسنا وبيتنا.',1,NULL,'التعرف على أهمية النظافة في الإسلام',6,NULL,2,NULL,'آداب النظافة',7),(209,NULL,NULL,'الإسلام يأمرنا بالرفق بالحيوان. نطعمها ونسقيها ولا نؤذيها.',1,NULL,'التعرف على أهمية الرفق بالحيوان',7,NULL,2,NULL,'الرفق بالحيوان',7),(210,NULL,NULL,'بر الوالدين واجب في الإسلام. نطيعهما ونحترمهما ونساعدهما ونتكلم معهما بأدب.',1,NULL,'التعرف على أهمية بر الوالدين',8,NULL,2,NULL,'بر الوالدين',7),(211,NULL,NULL,'حب الوطن من الإيمان. وطننا فلسطين نحبه وندافع عنه ونحافظ عليه.',1,NULL,'تعزيز قيمة حب الوطن',9,NULL,2,NULL,'حب الوطن',7),(212,NULL,NULL,'التعاون خلق إسلامي جميل. نساعد بعضنا البعض في البيت والمدرسة.',1,NULL,'التعرف على أهمية التعاون',10,NULL,2,NULL,'التعاون',7),(213,NULL,NULL,'مراجعة شاملة: السور القرآنية، خلق الله، الآداب الإسلامية، الأخلاق.',1,NULL,'مراجعة شاملة لمحتوى الفصل الثاني',11,NULL,2,NULL,'مراجعة عامة',7),(214,NULL,NULL,'أنا مسلم، ديني الإسلام، نبيي محمد ﷺ، كتابي القرآن الكريم. أعبد الله وحده وأحب رسوله.',2,NULL,'التعرف على معنى الإسلام والاعتزاز بالهوية الإسلامية.',1,NULL,1,NULL,'أنا مسلم',8),(215,NULL,NULL,'الله وحده المعبود بحق، لا شريك له. نعبده ولا نشرك به شيئاً. التوحيد إفراد الله بالعبادة.',2,NULL,'ترسيخ توحيد الله وإفراده بالعبادة.',2,NULL,1,NULL,'الله المعبود',8),(216,NULL,NULL,'قل يا أيها الكافرون. لا أعبد ما تعبدون. ولا أنتم عابدون ما أعبد. سورة مكية فيها البراءة من الشرك.',2,NULL,'حفظ سورة الكافرون وفهم معناها العام، وغرس الثبات على الإسلام.',3,NULL,1,NULL,'سورة الكافرون',8),(217,NULL,NULL,'كان النبي ﷺ في صغره يرعى الغنم، وفي شبابه عمل في التجارة لخديجة رضي الله عنها، وكان معروفاً بالصدق والأمانة فلقّبوه بالصادق الأمين.',2,NULL,'التعرف على اعتماد النبي ﷺ على نفسه في كسب رزقه، والتأسي به في العمل والاجتهاد.',4,NULL,1,NULL,'اعتماد الرسول ﷺ على نفسه',8),(218,NULL,NULL,'تزوج النبي ﷺ من السيدة خديجة بنت خويلد رضي الله عنها، وكان عمره خمساً وعشرين سنة وعمرها أربعين. كانت أول من آمن به وآزرته.',2,NULL,'التعرف على زوجة النبي ﷺ الأولى ودورها في دعم الدعوة.',5,NULL,1,NULL,'زواج الرسول ﷺ من خديجة رضي الله عنها',8),(219,NULL,NULL,'للنبي ﷺ سبعة أبناء: ثلاثة أولاد (القاسم وعبد الله وإبراهيم)، وأربع بنات (زينب ورقية وأم كلثوم وفاطمة). كلهم من خديجة إلا إبراهيم من السيدة مارية.',2,NULL,'حفظ أسماء أبناء النبي ﷺ ومعرفة أمهاتهم.',6,NULL,1,NULL,'أبناء الرسول ﷺ',8),(220,NULL,NULL,'كان النبي ﷺ قبل البعثة يخلو بنفسه في غار حراء في جبل النور قرب مكة، يتعبد ويتفكر في خلق الله. في هذا الغار نزل عليه الوحي أول مرة.',2,NULL,'التعرف على غار حراء وأهميته في بدء الوحي.',7,NULL,1,NULL,'في غار حراء',8),(221,NULL,NULL,'نزل الوحي على النبي ﷺ في غار حراء وهو في الأربعين من عمره. جاءه جبريل عليه السلام وقال له: \'اقرأ\'. كانت هذه أول كلمة نزلت من القرآن الكريم.',2,NULL,'التعرف على بداية نزول الوحي على النبي ﷺ.',8,NULL,1,NULL,'نزول الوحي',8),(222,NULL,NULL,'اقرأ باسم ربك الذي خلق. خلق الإنسان من علق. اقرأ وربك الأكرم. الذي علّم بالقلم. علّم الإنسان ما لم يعلم. أول ما نزل من القرآن.',2,NULL,'حفظ أوائل سورة العلق وفهم دلالاتها على فضل العلم والقراءة.',9,NULL,1,NULL,'سورة العلق',8),(223,NULL,NULL,'التعاون خلق إسلامي رفيع. قال تعالى: (وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى). نتعاون مع أهلنا وزملائنا وجيراننا على ما فيه الخير.',2,NULL,'ترسيخ خلق التعاون والاقتداء بالقرآن في الحث عليه.',10,NULL,1,NULL,'التعاون في الإسلام',8),(224,NULL,NULL,'قال النبي ﷺ: \'المسلم من سلم المسلمون من لسانه ويده\'. المسلم لا يؤذي إخوانه بالكلام السيئ ولا بيده.',2,NULL,'فهم الحديث الشريف وتطبيق معناه في السلوك اليومي.',11,NULL,1,NULL,'المسلم من سلم المسلمون من لسانه ويده',8),(225,NULL,NULL,'للطريق آداب عند المسلم: غض البصر، كف الأذى، رد السلام، الأمر بالمعروف والنهي عن المنكر، إفشاء السلام، إرشاد الضال.',2,NULL,'التعرف على آداب الطريق وتطبيقها.',12,NULL,1,NULL,'آداب الطريق',8),(226,NULL,NULL,'النظافة من الإيمان. مدرستي بيتي الثاني، أحافظ على نظافتها فلا أرمي ورقة على الأرض، ولا أكتب على الجدران، وأحرص على نظافة الفصل.',2,NULL,'غرس النظافة في البيئة المدرسية ومسؤولية الطالب نحوها.',13,NULL,1,NULL,'مدرستي نظيفة',8),(227,NULL,NULL,'أمرنا الإسلام بالرفق بالحيوان. قال النبي ﷺ: \'إن الله كتب الإحسان على كل شيء\'. نطعم الحيوان ونسقيه ولا نؤذيه ولا نحمّله ما لا يطيق.',2,NULL,'غرس الرحمة بالحيوان وتعليم الإحسان إليه.',14,NULL,1,NULL,'الرفق بالحيوان (الصف الثاني)',8),(228,NULL,NULL,'للقرآن الكريم آداب عند التلاوة: الوضوء، استقبال القبلة إن أمكن، الاستعاذة قبل القراءة، البسملة في غير سورة براءة، الترتيل، الإنصات لمن يقرأ.',2,NULL,'تعلم آداب تلاوة القرآن الكريم وتطبيقها.',15,NULL,1,NULL,'آداب التلاوة',8),(229,NULL,NULL,'تبت يدا أبي لهب وتب. ما أغنى عنه ماله وما كسب. سيصلى ناراً ذات لهب. وامرأته حمالة الحطب. في جيدها حبل من مسد. سورة فيها إنذار من عاقبة عداوة الإسلام.',2,NULL,'حفظ سورة المسد كاملة وفهم معانيها.',16,NULL,1,NULL,'سورة المسد (الصف الثاني)',8),(230,NULL,NULL,'قل أعوذ برب الفلق. من شر ما خلق. ومن شر غاسق إذا وقب. ومن شر النفاثات في العقد. ومن شر حاسد إذا حسد. سورة من المعوذتين.',2,NULL,'حفظ سورة الفلق كاملة وفهم أنها استعاذة بالله من الشرور.',17,NULL,1,NULL,'سورة الفلق (الصف الثاني)',8),(231,NULL,NULL,'الله تعالى قادر على كل شيء. خلق السماوات والأرض، ويحيي ويميت، ويرزق العباد. لا يعجزه شيء في الأرض ولا في السماء.',2,NULL,'ترسيخ الإيمان بقدرة الله المطلقة وأنه على كل شيء قدير.',1,NULL,2,NULL,'الله القادر',8),(232,NULL,NULL,'الله تعالى بصير يرى كل شيء، لا تخفى عليه خافية في الأرض ولا في السماء. يرى أعمالنا في السر والعلانية.',2,NULL,'ترسيخ مراقبة الله ومعرفة أنه يرى كل أعمالنا.',2,NULL,2,NULL,'الله البصير',8),(233,NULL,NULL,'لإيلاف قريش. إيلافهم رحلة الشتاء والصيف. فليعبدوا رب هذا البيت. الذي أطعمهم من جوع وآمنهم من خوف. سورة مكية فيها تذكير قريش بنعم الله.',2,NULL,'حفظ سورة قريش وفهم معناها العام.',3,NULL,2,NULL,'سورة قريش',8),(234,NULL,NULL,'الأذان نداء للصلاة. كلماته: الله أكبر، أشهد أن لا إله إلا الله، أشهد أن محمداً رسول الله، حي على الصلاة، حي على الفلاح، الله أكبر، لا إله إلا الله. نُجيب المؤذن بمثل ما يقول.',2,NULL,'حفظ كلمات الأذان وآداب الاستماع إليه.',4,NULL,2,NULL,'الأذان',8),(235,NULL,NULL,'دعاء الاستفتاح: سبحانك اللهم وبحمدك، وتبارك اسمك، وتعالى جدك، ولا إله غيرك. نقوله بعد تكبيرة الإحرام وقبل قراءة الفاتحة.',2,NULL,'حفظ دعاء الاستفتاح ومعرفة موضعه في الصلاة.',5,NULL,2,NULL,'دعاء الاستفتاح',8),(236,NULL,NULL,'التشهد: التحيات لله والصلوات والطيبات، السلام عليك أيها النبي ورحمة الله وبركاته، السلام علينا وعلى عباد الله الصالحين، أشهد أن لا إله إلا الله وأشهد أن محمداً عبده ورسوله. ثم نقول الصلاة الإبراهيمية.',2,NULL,'حفظ التشهد والصلاة الإبراهيمية ومعرفة موضعهما في الصلاة.',6,NULL,2,NULL,'التشهد والصلاة الإبراهيمية',8),(237,NULL,NULL,'أرأيت الذي يكذب بالدين. فذلك الذي يدعّ اليتيم. ولا يحضّ على طعام المسكين. فويل للمصلين. الذين هم عن صلاتهم ساهون. الذين هم يراؤون. ويمنعون الماعون. سورة فيها صفات المُكذّب بالدين.',2,NULL,'حفظ سورة الماعون وفهم صفات من يكذب بالدين.',7,NULL,2,NULL,'سورة الماعون',8),(238,NULL,NULL,'الصلوات الخمس فرض على كل مسلم بالغ. هي: الفجر، الظهر، العصر، المغرب، العشاء. الصلاة عماد الدين وأول ما يحاسب عليه العبد يوم القيامة.',2,NULL,'معرفة الصلوات الخمس وفضلها ومنزلتها في الإسلام.',8,NULL,2,NULL,'الصلوات الخمس',8),(239,NULL,NULL,'صلاة الفجر ركعتان جهرية. وقتها من طلوع الفجر الصادق إلى طلوع الشمس. هي أول صلاة في اليوم.',2,NULL,'معرفة عدد ركعات صلاة الفجر ووقتها وكيفيتها.',9,NULL,2,NULL,'صلاة الفجر',8),(240,NULL,NULL,'صلاة الظهر والعصر والعشاء كل واحدة منها أربع ركعات. الظهر والعصر سرية القراءة، أما العشاء فالركعتان الأوليان جهرية والركعتان الأخريان سرية.',2,NULL,'معرفة عدد ركعات هذه الصلوات وكيفية القراءة فيها.',10,NULL,2,NULL,'صلاة الظهر والعصر والعشاء',8),(241,NULL,NULL,'صلاة المغرب ثلاث ركعات: الركعتان الأوليان جهرية والثالثة سرية. وقتها من غروب الشمس إلى دخول وقت العشاء.',2,NULL,'معرفة عدد ركعات صلاة المغرب ووقتها وكيفية القراءة فيها.',11,NULL,2,NULL,'صلاة المغرب',8),(242,NULL,NULL,'المسجد بيت الله. ندخله بأدب: نتوضأ قبل دخوله، ندخل بالقدم اليمنى ونقول \'بسم الله، اللهم افتح لي أبواب رحمتك\'. نصلي ركعتين تحية المسجد. لا نلعب ولا نرفع أصواتنا فيه.',2,NULL,'تعلم آداب دخول المسجد والتعامل فيه.',12,NULL,2,NULL,'في المسجد',8),(243,NULL,NULL,'الصدق من أعظم الأخلاق في الإسلام. الصادق محبوب عند الله وعند الناس. كان النبي ﷺ يُعرف بالصادق الأمين قبل بعثته. الصدق يهدي إلى البر، والبر يهدي إلى الجنة.',2,NULL,'ترسيخ خلق الصدق وفضله وآثاره في المجتمع.',13,NULL,2,NULL,'الصدق (الصف الثاني)',8),(244,NULL,NULL,'الاعتماد على النفس خُلق إسلامي. أؤدّي واجباتي المدرسية بنفسي، وأرتّب فراشي وغرفتي بنفسي، ولا أكلّف الآخرين بما أستطيع فعله.',2,NULL,'غرس خلق الاعتماد على النفس في الأمور اليومية.',14,NULL,2,NULL,'الاعتماد على النفس (الصف الثاني)',8),(245,NULL,NULL,'الاستئذان أدب إسلامي قبل الدخول على الآخرين. نطرق الباب ثلاث مرات بأدب ونقول السلام عليكم. إذا أُذن لنا دخلنا، وإن لم يؤذن رجعنا دون غضب.',2,NULL,'تعلم آداب الاستئذان وتطبيقها في الحياة اليومية.',15,NULL,2,NULL,'الاستئذان',8),(246,NULL,NULL,'للزيارة آداب: اختيار وقت مناسب، الاستئذان قبل الدخول، إلقاء السلام، الجلوس حيث يُشير المضيف، عدم إطالة الزيارة، شكر المضيف عند الانصراف.',2,NULL,'تعلم آداب زيارة الآخرين وتطبيقها.',16,NULL,2,NULL,'آداب الزيارة',8),(247,NULL,NULL,'علّمنا النبي ﷺ توقير الكبير والعطف على الصغير. قال ﷺ: \'ليس منا من لم يرحم صغيرنا ويوقّر كبيرنا\'. نقف للكبير، ونحترمه، ونلين الكلام للصغير.',2,NULL,'غرس خلق توقير الكبار والرحمة بالصغار.',17,NULL,2,NULL,'توقير الكبير والعطف على الصغير',8),(248,NULL,NULL,'إنا أعطيناك الكوثر. فصلِّ لربك وانحر. إن شانئك هو الأبتر. أقصر سورة في القرآن الكريم، فيها بشارة للنبي ﷺ.',2,NULL,'حفظ سورة الكوثر وفهم بشارة الله لنبيه ﷺ.',18,NULL,2,NULL,'سورة الكوثر',8),(249,NULL,NULL,'ألم نشرح لك صدرك. ووضعنا عنك وزرك. الذي أنقض ظهرك. ورفعنا لك ذكرك. فإن مع العسر يسراً. إن مع العسر يسراً. فإذا فرغت فانصب. وإلى ربك فارغب. سورة فيها تطمين للنبي ﷺ.',2,NULL,'حفظ سورة الشرح وفهم بشارتها بأن مع العسر يسراً.',19,NULL,2,NULL,'سورة الشرح',8);
/*!40000 ALTER TABLE `lessons` ENABLE KEYS */;
