  `question_text` text NOT NULL,
  `sub_skill` varchar(32) DEFAULT NULL,
  `type` enum('FILL_BLANK','MCQ','ORDERING','PRONUNCIATION','SHORT_ANSWER','TRACING','TRUE_FALSE') NOT NULL,
  `lesson_id` bigint(20) NOT NULL,
