  CONSTRAINT `FKmoaj9c9k8ncsywujtcaujs6rt` FOREIGN KEY (`lesson_id`) REFERENCES `lessons` (`id`),
  CONSTRAINT `CONSTRAINT_1` CHECK (`difficulty_level` between 1 and 3)
